  "UTVendorGpuTasks": {
    "Content": "GPU vendor telemetry and updater tasks off",
    "Description": "Disables the NVIDIA and AMD scheduled tasks that report telemetry and check for driver updates in the background (NVIDIA Telemetry Monitor and Reporter, the daily driver update check, GeForce Experience self-update, the AMD user experience and updater tasks). The driver, the control panel and the overlay are untouched, and nothing is deleted: the tasks are disabled the same way Task Scheduler disables them, and undo puts back exactly what was enabled before. Installing a new GPU driver re-creates and re-enables them, so expect to run this again after a driver update.",
    "Evidence": "NvTmMon is the NVIDIA Telemetry Monitor and NvTmRep the crash and telemetry reporter (gHacks, PC Perspective); the SelfUpdate and DriverUpdateCheck tasks poll for updates. Disabling them has no effect on the driver or the control panel. Task names were checked against a live machine on the current driver, which is why they are matched by pattern. Confidence: medium.",
    "Category": "Background load",
    "Tier": "optional",
    "Recommended": false,
    "Order": 153,
    "InvokeScript": [
      "$patterns = @('NvTmRep*', 'NvTmMon*', 'NvProfileUpdater*', 'NvNodeLauncher*', 'NvDriverUpdateCheckDaily*', 'NVIDIA GeForce Experience SelfUpdate*', 'NVIDIA App SelfUpdate*', 'AMD User Experience Program*', 'AMDRyzenMasterSDKTask*', 'AMDInstallLauncher*', 'AMDLinkUpdate*', 'AMDRadeonSoftware*'); $found = 0; foreach ($task in @(Get-ScheduledTask -ErrorAction SilentlyContinue | Where-Object { $_.TaskPath -eq '\\' })) { $match = $false; foreach ($p in $patterns) { if ($task.TaskName -like $p) { $match = $true; break } }; if (-not $match) { continue }; $found++; Save-UTScriptState -Id UTVendorGpuTasks -Key $task.TaskName -Value ([string]$task.State); if ([string]$task.State -eq 'Disabled') { Write-UTLog \"$($task.TaskName): already disabled\"; continue }; try { $task | Disable-ScheduledTask -ErrorAction Stop | Out-Null; Write-UTLog \"$($task.TaskName) -> Disabled\" } catch { throw \"could not disable $($task.TaskName): $($_.Exception.Message)\" } }; if ($found -eq 0) { Write-UTLog 'No NVIDIA or AMD telemetry or updater tasks are present on this PC, nothing to change' }"
    ],
    "UndoScript": [
      "$state = Get-UTScriptState -Id UTVendorGpuTasks; if (-not $state) { Write-UTLog 'No recorded vendor task states, so nothing was re-enabled' -Level Warn } else { $failed = @(); foreach ($name in @($state.Keys)) { if ($state[$name] -eq 'Disabled') { Write-UTLog \"$name was already disabled before, left alone\"; continue }; $task = Get-ScheduledTask -TaskPath '\\' -TaskName $name -ErrorAction SilentlyContinue; if (-not $task) { Write-UTLog \"$name is no longer present, skipped\"; continue }; try { $task | Enable-ScheduledTask -ErrorAction Stop | Out-Null; Write-UTLog \"$name -> Enabled\" } catch { $failed += $name; Write-UTLog \"$name could not be re-enabled: $($_.Exception.Message)\" -Level Error } }; if ($failed.Count -gt 0) { throw (\"could not re-enable {0}; the snapshot is kept so undo can be retried\" -f ($failed -join ', ')) } }"
    ]
  },
  "UTHVCIOff": {
    "Content": "Memory integrity (core isolation) off",
    "Description": "RISKY. Memory integrity (HVCI) costs roughly 4 to 8 percent FPS on many systems (Tom's Hardware measured 4 to 6 percent average). Turning it off lowers Windows kernel protection against malicious drivers. As of the last check Riot Vanguard did not require it on Windows 10/11 x64 and Easy Anti-Cheat required it only on Arm and Insider builds, but anti-cheat requirements change without notice: if Valorant or another protected game stops launching, turn this back on first. Windows may prompt to re-enable it after feature updates. Reboot required.",
    "Evidence": "The Enabled value under DeviceGuard\\Scenarios\\HypervisorEnforcedCodeIntegrity is what the Windows Security Memory integrity switch writes (Microsoft Learn). Tom's Hardware measured HVCI/VBS costing 4 to 6 percent on average and up to 10 to 15 percent in CPU-bound titles. Confidence: high.",
    "Category": "Risky",
    "Tier": "risky",
    "Recommended": false,
    "Order": 200,
    "Reboot": true,
    "registry": [
      {
        "Path": "HKLM:\\SYSTEM\\CurrentControlSet\\Control\\DeviceGuard\\Scenarios\\HypervisorEnforcedCodeIntegrity",
        "Name": "Enabled",
        "Type": "DWord",
        "Value": "0",
        "OriginalValue": "1"
      }
    ],
    "GuardScript": [
      "if (Get-Service -Name vgk, vgc -ErrorAction SilentlyContinue) { Write-UTLog 'Riot Vanguard is installed on this PC. If Valorant stops launching after this change, undo it first before anything else.' -Level Warn }"
    ],
    "InvokeScript": [
      "try { $dg = Get-CimInstance -Namespace 'root\\Microsoft\\Windows\\DeviceGuard' -ClassName Win32_DeviceGuard -ErrorAction Stop; if (@($dg.SecurityServicesRunning) -contains 1) { Write-UTLog 'Credential Guard is running on this PC: the hypervisor stays on even with memory integrity off, so the FPS gain will be smaller' -Level Warn } } catch { }"
    ]
  },
  "UTVBSOff": {
    "Content": "Virtualization-based security off (the whole hypervisor)",
    "Description": "RISKY. Memory integrity is only one thing running inside VBS; the Windows hypervisor underneath it costs frames on its own. Tom's Hardware measured VBS on by default costing up to 10 percent, and about 5 percent geomean across four platforms, worst in CPU-bound competitive titles. This sets the Group Policy value that turns VBS off and stops the hypervisor from launching at boot. It breaks Hyper-V, WSL2, Windows Sandbox, Android subsystem and Docker's WSL backend, and it turns off Credential Guard. Riot's own VAN9005 article tells Windows 10 players to disable VBS, but anti-cheat requirements change without notice: if a protected game stops launching, undo this first. Windows 11 24H2 sometimes re-enables it after an update. If BitLocker or Device Encryption is on, protection is suspended for one reboot first so you do not get a recovery-key prompt. Reboot required.",
    "Evidence": "EnableVirtualizationBasedSecurity=0 is the disabled value of the Turn On Virtualization Based Security policy, read from C:\\Windows\\PolicyDefinitions\\DeviceGuard.admx, and hypervisorlaunchtype off stops the Windows hypervisor at boot (Microsoft Learn, BCDEdit). Tom's Hardware measured VBS costing up to 10 percent on an RTX 4090 system, about 5 percent geomean across four platforms. Confidence: high.",
    "Category": "Risky",
    "Tier": "risky",
    "Recommended": false,
    "Order": 201,
    "Reboot": true,
    "GuardScript": [
      "$vm = @(); if (Get-Service -Name vmcompute, vmms -ErrorAction SilentlyContinue) { $vm += 'Hyper-V' }; if (Get-Service -Name LxssManager -ErrorAction SilentlyContinue) { $vm += 'WSL' }; if ($vm.Count -gt 0) { Write-UTLog (\"This PC has {0} installed. Turning the hypervisor off stops it working until you undo this tweak.\" -f ($vm -join ' and ')) -Level Warn }"
    ],
    "registry": [
      {
        "Path": "HKLM:\\SOFTWARE\\Policies\\Microsoft\\Windows\\DeviceGuard",
        "Name": "EnableVirtualizationBasedSecurity",
        "Type": "DWord",
        "Value": "0",
        "OriginalValue": "<RemoveEntry>"
      }
    ],
    "InvokeScript": [
      "try { $dg = Get-CimInstance -Namespace 'root\\Microsoft\\Windows\\DeviceGuard' -ClassName Win32_DeviceGuard -ErrorAction Stop; if ([int]$dg.VirtualizationBasedSecurityStatus -eq 0) { Write-UTLog 'VBS was already off on this PC, so there are no frames to win back; the policy value is still written so a Windows update cannot switch it back on' } elseif (@($dg.SecurityServicesRunning) -contains 1) { Write-UTLog 'Credential Guard is running. If it was enabled with UEFI lock, Windows keeps the hypervisor on and this change will not take effect until you clear the lock.' -Level Warn } } catch { }",
      "Invoke-UTBcdEdit -Arguments '/set hypervisorlaunchtype off'"
    ],
    "UndoScript": [
      "Invoke-UTBcdEdit -Arguments '/set hypervisorlaunchtype Auto'"
    ]
  },
  "UTDynamicTickOff": {
    "Content": "Dynamic timer tick off (bcdedit)",
    "Description": "RISKY. Keeps the clock interrupt at a fixed rate instead of tickless idle. Microsoft documents this as a debugging option; there is no reproducible FPS benchmark either way and it costs idle power. If BitLocker or Device Encryption is on, protection is suspended for one reboot first so you do not get a recovery-key prompt. Reboot required.",
    "Evidence": "disabledynamictick is a documented BCDEdit option that Microsoft lists for debugging (Microsoft Learn, BCDEdit /set). No reproducible FPS benchmark exists either way, and it costs idle power. Confidence: high that it does what it says, low for any gain.",
    "Category": "Risky",
    "Tier": "risky",
    "Recommended": false,
    "Order": 202,
    "Reboot": true,
    "InvokeScript": [
      "Invoke-UTBcdEdit -Arguments '/set disabledynamictick yes'"
    ],
    "UndoScript": [
      "Invoke-UTBcdEdit -Arguments '/deletevalue disabledynamictick'"
    ]
  },
  "UTTimerResGlobal": {
    "Content": "Global timer resolution requests (Windows 11)",
    "Description": "RISKY. Windows 11 / Server 2022 only key: it makes one process's high timer-resolution request apply system-wide again, the way Windows did before 10 v2004. It does nothing on its own - something still has to request the resolution - and this project ships no timer tool. Microsoft's own guidance, and valleyofdoom/TimerResolution, say it is for debugging. Costs idle power. Reboot required.",
    "Evidence": "GlobalTimerResolutionRequests is the Windows 11 / Server 2022 key that restores the pre-2004 behaviour where one process's timer-resolution request applies system-wide (valleyofdoom/TimerResolution, which documents it as debugging-only). Inert on Windows 10. Confidence: medium.",
    "Category": "Risky",
    "Tier": "risky",
    "Recommended": false,
    "Order": 203,
    "MinBuild": 22000,
    "Reboot": true,
    "registry": [
      {
        "Path": "HKLM:\\SYSTEM\\CurrentControlSet\\Control\\Session Manager\\kernel",
        "Name": "GlobalTimerResolutionRequests",
        "Type": "DWord",
        "Value": "1",
        "OriginalValue": "<RemoveEntry>"
      }
    ]
  },
  "UTMSIModeGPU": {
    "Content": "Message Signaled Interrupts on the GPU",
    "Description": "RISKY. Enables MSI mode on every display adapter that is still using line-based interrupts. Modern NVIDIA, AMD and Intel drivers already enable MSI, in which case nothing changes. On a device that does not support MSI the PC can hang at boot; recovery is Safe Mode. Per-device previous values are recorded for undo. Reboot required.",
    "Evidence": "MSISupported=1 under Interrupt Management\\MessageSignaledInterruptProperties switches the device to message-signaled interrupts (Microsoft Learn, Enabling MSI). Modern GPU drivers already enable it; a device that cannot support it can hang at boot. Confidence: high.",
    "Category": "Risky",
    "Tier": "risky",
    "Recommended": false,
    "Order": 204,
    "Reboot": true,
    "InvokeScript": [
      "Get-PnpDevice -Class Display -PresentOnly -ErrorAction SilentlyContinue | ForEach-Object { $inst = $_.InstanceId; if ($inst -notlike 'PCI\\*') { return }; $key = \"HKLM:\\SYSTEM\\CurrentControlSet\\Enum\\$inst\\Device Parameters\\Interrupt Management\\MessageSignaledInterruptProperties\"; $cur = $null; if (Test-Path $key) { $cur = (Get-ItemProperty $key -Name MSISupported -ErrorAction SilentlyContinue).MSISupported }; if ($null -eq $cur) { Save-UTScriptState -Id UTMSIModeGPU -Key $inst -Value 'missing' } else { Save-UTScriptState -Id UTMSIModeGPU -Key $inst -Value ([string]$cur) }; if ($cur -eq 1) { Write-UTLog \"$($_.FriendlyName): MSI already enabled, nothing to do\"; return }; if (-not (Test-Path $key)) { New-Item $key -Force | Out-Null }; Set-ItemProperty $key -Name MSISupported -Type DWord -Value 1 -Force; Write-UTLog \"$($_.FriendlyName): MSI enabled (previous value: $cur)\" }"
    ],
    "UndoScript": [
      "$state = Get-UTScriptState -Id UTMSIModeGPU; if ($state) { foreach ($k in @($state.Keys)) { $key = \"HKLM:\\SYSTEM\\CurrentControlSet\\Enum\\$k\\Device Parameters\\Interrupt Management\\MessageSignaledInterruptProperties\"; if (-not (Test-Path $key)) { continue }; if ($state[$k] -eq 'missing') { Remove-ItemProperty $key -Name MSISupported -ErrorAction SilentlyContinue } else { Set-ItemProperty $key -Name MSISupported -Type DWord -Value ([int]$state[$k]) -Force }; Write-UTLog \"MSI setting restored for $k\" } }"
    ]
  },
  "UTGamePriorityIFEO": {
    "Content": "Fortnite process priority Above Normal (registry, survives EAC)",
    "Description": "RISKY. Sets the Image File Execution Options PerfOptions CpuPriorityClass to Above Normal for FortniteClient-Win64-Shipping.exe. The kernel applies it at process start, so it works even though Easy Anti-Cheat blocks external priority changes. High and Realtime are deliberately not offered: they starve input and audio threads. No ban reports exist for priority changes; code injection is what gets people banned, and this injects nothing.",
    "Evidence": "PerfOptions\\CpuPriorityClass under Image File Execution Options is applied by the loader when the process starts (IFEO PerfOptions reference); 6 is Above Normal. Because the kernel sets it rather than an external tool, Easy Anti-Cheat cannot block it. No ban reports exist for priority changes. Confidence: medium.",
    "Category": "Risky",
    "Tier": "risky",
    "Recommended": false,
    "Order": 205,
    "registry": [
      {
        "Path": "HKLM:\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Image File Execution Options\\FortniteClient-Win64-Shipping.exe\\PerfOptions",
        "Name": "CpuPriorityClass",
        "Type": "DWord",
        "Value": "6",
        "OriginalValue": "<RemoveEntry>"
      }
    ]
  },
  "UTCoreParkingOff": {
    "Content": "Core parking off (plugged in)",
    "Description": "RISKY. Forces all cores to stay unparked. Gives little or nothing on desktop CPUs that do not park, and actively hurts AMD X3D dual-CCD and Intel hybrid CPUs where Windows parks cores on purpose. X3D CPUs are skipped automatically. The previous value is recorded for undo.",
    "Evidence": "CPMINCORES is the documented Processor performance core parking min cores power setting (Microsoft Learn); 100 keeps every core unparked. Since Skylake and Zen, parking control moved on-die, so the classic gain is mostly gone, and AMD X3D dual-CCD and Intel hybrid CPUs rely on parking to keep games on the right cores. Confidence: high.",
    "Category": "Risky",
    "Tier": "risky",
    "Recommended": false,
    "Order": 206,
    "GuardScript": [
      "$cpu = (Get-CimInstance Win32_Processor | Select-Object -First 1).Name; if ($cpu -match 'X3D') { throw \"refused on $cpu : this CPU relies on core parking to keep games on the V-Cache die\" }"
    ],
    "InvokeScript": [
      "$cur = Get-UTPowerCfgIndex -SubGroup 'SUB_PROCESSOR' -Setting 'CPMINCORES'; if ($null -eq $cur) { throw 'could not read the current core parking minimum, so it was not changed' }; Save-UTScriptState -Id UTCoreParkingOff -Key CPMINCORES -Value $cur; powercfg /setacvalueindex SCHEME_CURRENT SUB_PROCESSOR CPMINCORES 100 | Out-Null; powercfg /setactive SCHEME_CURRENT | Out-Null"
    ],
    "UndoScript": [
      "$cur = Get-UTScriptState -Id UTCoreParkingOff -Key CPMINCORES; if ($null -eq $cur -or $cur -eq '') { powercfg -restoredefaultschemes | Out-Null; Write-UTLog 'No recorded core parking value, so the power schemes were restored to Windows defaults' -Level Warn } else { powercfg /setacvalueindex SCHEME_CURRENT SUB_PROCESSOR CPMINCORES $cur | Out-Null; powercfg /setactive SCHEME_CURRENT | Out-Null }"
    ]
  },
  "UTSysMainOff": {
    "Content": "SysMain (Superfetch) off",
    "Description": "RISKY (low value). Disables the memory prefetching service. On an SSD there is no measurable FPS gain and app launches get slower; some people report fewer HDD stutters. Included only because it is requested so often.",
    "Evidence": "SysMain is the Superfetch/prefetch service. Windows already disables prefetch behaviour on SSDs, so there is no measurable FPS gain and app launches get slower. Kept only because it is requested so often. Confidence: medium.",
    "Category": "Risky",
    "Tier": "risky",
    "Recommended": false,
    "Order": 207,
    "service": [
      {
        "Name": "SysMain",
        "StartupType": "Disabled",
        "OriginalType": "Automatic"
      }
    ],
    "Reboot": true
  }
}
'@ | ConvertFrom-Json

$inputXML = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="unknowntweaks" Width="1280" Height="820" MinWidth="1000" MinHeight="640"
        WindowStartupLocation="CenterScreen" Background="#1E1E1E" Foreground="#D4D4D4"
        FontFamily="Cascadia Mono, Consolas, Courier New" FontSize="12.5"
        UseLayoutRounding="True" SnapsToDevicePixels="True" TextOptions.TextFormattingMode="Display">
  <Window.Resources>
    <SolidColorBrush x:Key="Bg0" Color="#1E1E1E"/>
    <SolidColorBrush x:Key="Bg1" Color="#252526"/>
    <SolidColorBrush x:Key="Bg2" Color="#2D2D30"/>
    <SolidColorBrush x:Key="Bg3" Color="#3E3E42"/>
    <SolidColorBrush x:Key="BorderBrush" Color="#3E3E42"/>
    <SolidColorBrush x:Key="Fg" Color="#D4D4D4"/>
    <SolidColorBrush x:Key="FgDim" Color="#858585"/>
    <SolidColorBrush x:Key="Accent" Color="#007ACC"/>
    <SolidColorBrush x:Key="AccentHover" Color="#1C97EA"/>
    <SolidColorBrush x:Key="Green" Color="#4EC9B0"/>
    <SolidColorBrush x:Key="Orange" Color="#CE9178"/>
    <SolidColorBrush x:Key="Yellow" Color="#DCDCAA"/>
    <SolidColorBrush x:Key="Red" Color="#F14C4C"/>
    <SolidColorBrush x:Key="Blue" Color="#569CD6"/>
    <SolidColorBrush x:Key="Purple" Color="#C586C0"/>
    <SolidColorBrush x:Key="ScrollTrack" Color="#1E1E1E"/>
    <SolidColorBrush x:Key="ScrollThumb" Color="#424242"/>
    <SolidColorBrush x:Key="ScrollThumbHover" Color="#4F4F4F"/>
    <FontFamily x:Key="MonoFont">Cascadia Mono, Cascadia Code, Consolas, Courier New</FontFamily>

    <DrawingBrush x:Key="GridBrush" TileMode="Tile" Viewport="0,0,16,16" ViewportUnits="Absolute" Opacity="0.7" RenderOptions.CachingHint="Cache">
      <DrawingBrush.Drawing>
        <GeometryDrawing>
          <GeometryDrawing.Geometry>
            <GeometryGroup>
              <LineGeometry StartPoint="0,15.5" EndPoint="16,15.5"/>
              <LineGeometry StartPoint="15.5,0" EndPoint="15.5,16"/>
            </GeometryGroup>
          </GeometryDrawing.Geometry>
          <GeometryDrawing.Pen>
            <Pen Brush="#2A2A2E" Thickness="1"/>
          </GeometryDrawing.Pen>
        </GeometryDrawing>
      </DrawingBrush.Drawing>
    </DrawingBrush>

    <Style x:Key="ScrollThumbStyle" TargetType="Thumb">
      <Setter Property="OverridesDefaultStyle" Value="True"/>
      <Setter Property="IsTabStop" Value="False"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Thumb">
            <Border x:Name="Bd" Background="{DynamicResource ScrollThumb}" CornerRadius="3" Margin="1"/>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter TargetName="Bd" Property="Background" Value="{DynamicResource ScrollThumbHover}"/>
              </Trigger>
              <Trigger Property="IsDragging" Value="True">
                <Setter TargetName="Bd" Property="Background" Value="{DynamicResource Accent}"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
    <Style x:Key="ScrollPageButton" TargetType="RepeatButton">
      <Setter Property="OverridesDefaultStyle" Value="True"/>
      <Setter Property="IsTabStop" Value="False"/>
      <Setter Property="Focusable" Value="False"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="RepeatButton"><Rectangle Fill="Transparent"/></ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
    <ControlTemplate x:Key="VScrollBarTemplate" TargetType="ScrollBar">
      <Grid Background="{DynamicResource ScrollTrack}" Width="8">
        <Track x:Name="PART_Track" IsDirectionReversed="True">
          <Track.DecreaseRepeatButton>
            <RepeatButton Style="{StaticResource ScrollPageButton}" Command="ScrollBar.PageUpCommand"/>
          </Track.DecreaseRepeatButton>
          <Track.IncreaseRepeatButton>
            <RepeatButton Style="{StaticResource ScrollPageButton}" Command="ScrollBar.PageDownCommand"/>
          </Track.IncreaseRepeatButton>
          <Track.Thumb><Thumb Style="{StaticResource ScrollThumbStyle}"/></Track.Thumb>
        </Track>
      </Grid>
    </ControlTemplate>
    <ControlTemplate x:Key="HScrollBarTemplate" TargetType="ScrollBar">
      <Grid Background="{DynamicResource ScrollTrack}" Height="8">
        <Track x:Name="PART_Track" IsDirectionReversed="False">
          <Track.DecreaseRepeatButton>
            <RepeatButton Style="{StaticResource ScrollPageButton}" Command="ScrollBar.PageLeftCommand"/>
          </Track.DecreaseRepeatButton>
          <Track.IncreaseRepeatButton>
            <RepeatButton Style="{StaticResource ScrollPageButton}" Command="ScrollBar.PageRightCommand"/>
          </Track.IncreaseRepeatButton>
          <Track.Thumb><Thumb Style="{StaticResource ScrollThumbStyle}"/></Track.Thumb>
        </Track>
      </Grid>
    </ControlTemplate>
    <Style TargetType="ScrollBar">
      <Setter Property="OverridesDefaultStyle" Value="True"/>
      <Setter Property="Stylus.IsFlicksEnabled" Value="False"/>
      <Setter Property="Width" Value="8"/>
      <Setter Property="MinWidth" Value="8"/>
      <Setter Property="Template" Value="{StaticResource VScrollBarTemplate}"/>
      <Style.Triggers>
        <Trigger Property="Orientation" Value="Horizontal">
          <Setter Property="Width" Value="Auto"/>
          <Setter Property="MinWidth" Value="0"/>
          <Setter Property="Height" Value="8"/>
          <Setter Property="MinHeight" Value="8"/>
          <Setter Property="Template" Value="{StaticResource HScrollBarTemplate}"/>
        </Trigger>
      </Style.Triggers>
    </Style>
    <Style TargetType="ScrollViewer">
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="ScrollViewer">
            <Grid>
              <Grid.ColumnDefinitions>
                <ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/>
              </Grid.ColumnDefinitions>
              <Grid.RowDefinitions>
                <RowDefinition Height="*"/><RowDefinition Height="Auto"/>
              </Grid.RowDefinitions>
              <ScrollContentPresenter Grid.Column="0" Grid.Row="0" Margin="{TemplateBinding Padding}" CanContentScroll="{TemplateBinding CanContentScroll}"/>
              <ScrollBar x:Name="PART_VerticalScrollBar" Grid.Column="1" Grid.Row="0" Orientation="Vertical"
                         Value="{TemplateBinding VerticalOffset}" Maximum="{TemplateBinding ScrollableHeight}"
                         ViewportSize="{TemplateBinding ViewportHeight}" Visibility="{TemplateBinding ComputedVerticalScrollBarVisibility}"/>
              <ScrollBar x:Name="PART_HorizontalScrollBar" Grid.Column="0" Grid.Row="1" Orientation="Horizontal"
                         Value="{TemplateBinding HorizontalOffset}" Maximum="{TemplateBinding ScrollableWidth}"
                         ViewportSize="{TemplateBinding ViewportWidth}" Visibility="{TemplateBinding ComputedHorizontalScrollBarVisibility}"/>
            </Grid>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <Style TargetType="Button">
      <Setter Property="Background" Value="{DynamicResource Bg2}"/>
      <Setter Property="Foreground" Value="{DynamicResource Fg}"/>
      <Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/>
      <Setter Property="BorderThickness" Value="1"/>
      <Setter Property="Padding" Value="12,5"/>
      <Setter Property="Margin" Value="0,0,8,0"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Button">
            <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}"
                    BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="3" Padding="{TemplateBinding Padding}" SnapsToDevicePixels="True">
              <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" RecognizesAccessKey="True"/>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter TargetName="Bd" Property="Background" Value="{DynamicResource Bg3}"/>
                <Setter TargetName="Bd" Property="BorderBrush" Value="{DynamicResource Accent}"/>
              </Trigger>
              <Trigger Property="IsPressed" Value="True">
                <Setter TargetName="Bd" Property="Background" Value="{DynamicResource Accent}"/>
                <Setter Property="Foreground" Value="White"/>
              </Trigger>
              <Trigger Property="IsEnabled" Value="False">
                <Setter Property="Opacity" Value="0.45"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
    <Style x:Key="AccentButton" TargetType="Button" BasedOn="{StaticResource {x:Type Button}}">
      <Setter Property="Background" Value="{DynamicResource Accent}"/>
      <Setter Property="BorderBrush" Value="{DynamicResource Accent}"/>
      <Setter Property="Foreground" Value="White"/>
    </Style>
    <Style x:Key="DangerButton" TargetType="Button" BasedOn="{StaticResource {x:Type Button}}">
      <Setter Property="BorderBrush" Value="{DynamicResource Red}"/>
    </Style>

    <Style TargetType="CheckBox">
      <Setter Property="Foreground" Value="{DynamicResource Fg}"/>
      <Setter Property="Margin" Value="8,4,0,0"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="CheckBox">
            <Grid Background="Transparent">
              <Grid.ColumnDefinitions>
                <ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/>
              </Grid.ColumnDefinitions>
              <Border x:Name="Box" Width="16" Height="16" CornerRadius="3" BorderThickness="1"
                      BorderBrush="{DynamicResource FgDim}" Background="{DynamicResource Bg2}" VerticalAlignment="Top" Margin="0,1,0,0" SnapsToDevicePixels="True">
                <Path x:Name="Mark" Data="M 3,8 L 7,12 L 13,4" Stroke="White" StrokeThickness="2"
                      StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" Visibility="Collapsed" Stretch="None"/>
              </Border>
              <ContentPresenter Grid.Column="1" Margin="8,0,0,0" VerticalAlignment="Center" RecognizesAccessKey="True"/>
            </Grid>
            <ControlTemplate.Triggers>
              <Trigger Property="IsChecked" Value="True">
                <Setter TargetName="Box" Property="Background" Value="{DynamicResource Accent}"/>
                <Setter TargetName="Box" Property="BorderBrush" Value="{DynamicResource Accent}"/>
                <Setter TargetName="Mark" Property="Visibility" Value="Visible"/>
              </Trigger>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter TargetName="Box" Property="BorderBrush" Value="{DynamicResource AccentHover}"/>
              </Trigger>
              <Trigger Property="IsEnabled" Value="False">
                <Setter Property="Opacity" Value="0.45"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <Style TargetType="TabControl">
      <Setter Property="Background" Value="Transparent"/>
      <Setter Property="BorderThickness" Value="0"/>
      <Setter Property="Padding" Value="0"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="TabControl">
            <Grid KeyboardNavigation.TabNavigation="Local">
              <Grid.RowDefinitions>
                <RowDefinition Height="Auto"/><RowDefinition Height="*"/>
              </Grid.RowDefinitions>
              <Border Grid.Row="0" Background="{DynamicResource Bg1}" BorderBrush="{DynamicResource BorderBrush}" BorderThickness="0,0,0,1">
                <TabPanel IsItemsHost="True" Margin="6,0,0,0" KeyboardNavigation.TabIndex="1"/>
              </Border>
              <Border Grid.Row="1" Background="{DynamicResource Bg0}" KeyboardNavigation.TabNavigation="Local" KeyboardNavigation.DirectionalNavigation="Contained" KeyboardNavigation.TabIndex="2">
                <ContentPresenter x:Name="PART_SelectedContentHost" ContentSource="SelectedContent" Margin="{TemplateBinding Padding}"/>
              </Border>
            </Grid>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
    <Style TargetType="TabItem">
      <Setter Property="Foreground" Value="{DynamicResource FgDim}"/>
      <Setter Property="Padding" Value="14,8"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="TabItem">
            <Border x:Name="Root" Background="Transparent" BorderThickness="0,0,0,2" BorderBrush="Transparent" Padding="{TemplateBinding Padding}" Cursor="Hand" SnapsToDevicePixels="True">
              <ContentPresenter ContentSource="Header" HorizontalAlignment="Center" VerticalAlignment="Center" RecognizesAccessKey="True"/>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter Property="Foreground" Value="{DynamicResource Fg}"/>
              </Trigger>
              <Trigger Property="IsSelected" Value="True">
                <Setter TargetName="Root" Property="BorderBrush" Value="{DynamicResource Accent}"/>
                <Setter Property="Foreground" Value="{DynamicResource Fg}"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <Style TargetType="ListBox">
      <Setter Property="Background" Value="{DynamicResource Bg1}"/>
      <Setter Property="Foreground" Value="{DynamicResource Fg}"/>
      <Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/>
      <Setter Property="BorderThickness" Value="1"/>
      <Setter Property="ScrollViewer.HorizontalScrollBarVisibility" Value="Disabled"/>
    </Style>
    <Style TargetType="ListBoxItem">
      <Setter Property="Padding" Value="8,4"/>
      <Setter Property="Foreground" Value="{DynamicResource Fg}"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="ListBoxItem">
            <Border x:Name="Bd" Background="Transparent" Padding="{TemplateBinding Padding}" BorderThickness="2,0,0,0" BorderBrush="Transparent" SnapsToDevicePixels="True">
              <ContentPresenter/>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter TargetName="Bd" Property="Background" Value="{DynamicResource Bg2}"/>
              </Trigger>
              <Trigger Property="IsSelected" Value="True">
                <Setter TargetName="Bd" Property="Background" Value="{DynamicResource Bg3}"/>
                <Setter TargetName="Bd" Property="BorderBrush" Value="{DynamicResource Accent}"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <Style TargetType="TextBox">
      <Setter Property="Background" Value="{DynamicResource Bg0}"/>
      <Setter Property="Foreground" Value="{DynamicResource Fg}"/>
      <Setter Property="CaretBrush" Value="{DynamicResource Fg}"/>
      <Setter Property="SelectionBrush" Value="{DynamicResource Accent}"/>
      <Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/>
      <Setter Property="BorderThickness" Value="1"/>
      <Setter Property="Padding" Value="6,4"/>
      <Setter Property="FontFamily" Value="{DynamicResource MonoFont}"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="TextBox">
            <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" SnapsToDevicePixels="True">
              <ScrollViewer x:Name="PART_ContentHost" Margin="{TemplateBinding Padding}" Focusable="False"/>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="IsKeyboardFocused" Value="True">
                <Setter TargetName="Bd" Property="BorderBrush" Value="{DynamicResource Accent}"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <Style TargetType="ToolTip">
      <Setter Property="OverridesDefaultStyle" Value="True"/>
      <Setter Property="HasDropShadow" Value="False"/>
      <Setter Property="Background" Value="{DynamicResource Bg2}"/>
      <Setter Property="Foreground" Value="{DynamicResource Fg}"/>
      <Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/>
      <Setter Property="MaxWidth" Value="560"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="ToolTip">
            <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1" Padding="8,5" CornerRadius="3">
              <ContentPresenter>
                <ContentPresenter.Resources>
                  <Style TargetType="TextBlock">
                    <Setter Property="TextWrapping" Value="Wrap"/>
                    <Setter Property="Foreground" Value="{DynamicResource Fg}"/>
                  </Style>
                </ContentPresenter.Resources>
              </ContentPresenter>
            </Border>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>

    <Style TargetType="GridSplitter">
      <Setter Property="Background" Value="{DynamicResource BorderBrush}"/>
    </Style>
    <Style x:Key="GraphCard" TargetType="Border">
      <Setter Property="Background" Value="{DynamicResource Bg1}"/>
      <Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/>
      <Setter Property="BorderThickness" Value="1"/>
      <Setter Property="CornerRadius" Value="4"/>
      <Setter Property="Margin" Value="8,8,8,0"/>
      <Setter Property="Padding" Value="8"/>
    </Style>
    <Style x:Key="SectionHeader" TargetType="TextBlock">
      <Setter Property="Foreground" Value="{DynamicResource Blue}"/>
      <Setter Property="FontSize" Value="13"/>
      <Setter Property="FontWeight" Value="Bold"/>
      <Setter Property="Margin" Value="8,16,0,4"/>
    </Style>
    <Style x:Key="Dim" TargetType="TextBlock">
      <Setter Property="Foreground" Value="{DynamicResource FgDim}"/>
      <Setter Property="FontSize" Value="11"/>
      <Setter Property="TextWrapping" Value="Wrap"/>
      <Setter Property="Margin" Value="8,2,8,4"/>
    </Style>
    <Style x:Key="Body" TargetType="TextBlock">
      <Setter Property="Foreground" Value="{DynamicResource Fg}"/>
      <Setter Property="TextWrapping" Value="Wrap"/>
      <Setter Property="Margin" Value="8,4,8,4"/>
    </Style>
  </Window.Resources>

  <DockPanel>
    <Border DockPanel.Dock="Bottom" Background="#0E639C" Height="24">
      <DockPanel>
        <TextBlock Name="VersionText" DockPanel.Dock="Right" Text="" Foreground="White" VerticalAlignment="Center" Margin="10,0" FontSize="11"/>
        <TextBlock Name="TikTokLink" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="6,0" FontSize="11"><Hyperlink Name="TikTokHyperlink" Foreground="White">tiktok @aimerunknown</Hyperlink></TextBlock>
        <TextBlock Name="SupportLink" DockPanel.Dock="Right" VerticalAlignment="Center" Margin="6,0" FontSize="11"><Hyperlink Name="SupportHyperlink" Foreground="White">discord support</Hyperlink></TextBlock>
        <TextBlock Name="CreditText" DockPanel.Dock="Right" Text="" Foreground="White" FontWeight="Bold" VerticalAlignment="Center" Margin="10,0" FontSize="11"/>
        <TextBlock Name="StatusText" Text="starting..." Foreground="White" VerticalAlignment="Center" Margin="10,0" FontSize="11"/>
      </DockPanel>
    </Border>
    <Grid>
      <Grid.RowDefinitions>
        <RowDefinition Height="*"/>
        <RowDefinition Height="4"/>
        <RowDefinition Height="200" MinHeight="80"/>
      </Grid.RowDefinitions>
      <Grid Grid.Row="0">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="330" MinWidth="240"/>
          <ColumnDefinition Width="4"/>
          <ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>

        <Border Grid.Column="0" Background="#252526">
          <ScrollViewer VerticalScrollBarVisibility="Auto">
            <StackPanel Name="LeftPanel" Margin="0,0,0,8">
              <Border Margin="8,10,8,0" Padding="8,4">
                <StackPanel>
                  <TextBlock Text="unknowntweaks" FontSize="18" FontWeight="Bold" Foreground="#4EC9B0"/>
                  <TextBlock Text="free, open source, undoable" Foreground="#858585" FontSize="11"/>
                </StackPanel>
              </Border>
              <StackPanel Name="GraphPanel"/>
              <Border Style="{StaticResource GraphCard}">
                <StackPanel>
                  <TextBlock Text="GAME" Foreground="#858585" FontSize="12"/>
                  <TextBlock Name="GameText" Text="no fullscreen game detected" Foreground="#DCDCAA" Margin="0,4,0,0" TextWrapping="Wrap"/>
                  <TextBlock Name="GameDetailText" Text="" Foreground="#858585" FontSize="11" Margin="0,2,0,0" TextWrapping="Wrap"/>
                  <TextBlock Name="PingText" Text="router --  internet --" Foreground="#D4D4D4" Margin="0,8,0,0"/>
                  <TextBlock Name="RegionText" Text="best Fortnite region: not measured yet" Foreground="#D4D4D4" Margin="0,2,0,0" TextWrapping="Wrap"/>
                  <TextBlock Name="LinkText" Text="" Foreground="#858585" FontSize="11" Margin="0,4,0,0" TextWrapping="Wrap"/>
                  <StackPanel Orientation="Horizontal" Margin="0,8,0,0">
                    <Button Name="BtnPingRegionsSide" Content="ping regions" Padding="8,3" FontSize="11"/>
                    <Button Name="BtnBoostGame" Content="boost game priority" Padding="8,3" FontSize="11" ToolTip="Sets the foreground game process to High priority for this session. Anti-cheat protected games (Fortnite, Valorant) refuse this; use the registry tweak in the Risky section for Fortnite instead."/>
                  </StackPanel>
                </StackPanel>
              </Border>
            </StackPanel>
          </ScrollViewer>
        </Border>
        <GridSplitter Grid.Column="1" HorizontalAlignment="Stretch" VerticalAlignment="Stretch"/>

        <TabControl Grid.Column="2" Name="Tabs">
          <TabItem Header="TWEAKS">
            <DockPanel>
              <Border DockPanel.Dock="Top" Background="#252526" BorderBrush="#3E3E42" BorderThickness="0,0,0,1" Padding="10,8">
                <DockPanel>
                  <StackPanel DockPanel.Dock="Right" Orientation="Horizontal">
                    <Button Name="BtnUndoAll" Content="Undo everything" Style="{StaticResource DangerButton}" ToolTip="Reverts every tweak unknowntweaks has ever applied on this PC, using the snapshots it took, even from an earlier session."/>
                    <Button Name="BtnUndo" Content="Undo selected"/>
                    <Button Name="BtnApply" Content="Apply selected" Style="{StaticResource AccentButton}" Margin="0"/>
                  </StackPanel>
                  <StackPanel Orientation="Horizontal">
                    <Button Name="BtnRecommended" Content="Select recommended"/>
                    <Button Name="BtnClearTweaks" Content="Clear"/>
                    <CheckBox Name="ChkRestorePoint" Content="create a restore point first" IsChecked="True" VerticalAlignment="Center" Margin="8,0,0,0"/>
                  </StackPanel>
                </DockPanel>
              </Border>
              <ScrollViewer VerticalScrollBarVisibility="Auto">
                <StackPanel Name="TweaksPanel" Margin="8,4,8,16"/>
              </ScrollViewer>
            </DockPanel>
          </TabItem>

          <TabItem Header="FORTNITE">
            <ScrollViewer VerticalScrollBarVisibility="Auto">
              <StackPanel Margin="8,4,8,16">
                <TextBlock Text="Fortnite" Style="{StaticResource SectionHeader}"/>
                <TextBlock Name="FnStatusText" Style="{StaticResource Body}" Text="detecting..."/>
                <TextBlock Text="Video settings profile (GameUserSettings.ini)" Style="{StaticResource SectionHeader}"/>
                <ListBox Name="FnProfileList" Margin="8,4,8,4" Height="96"/>
                <TextBlock Name="FnProfileDesc" Style="{StaticResource Dim}" Text=""/>
                <StackPanel Name="FnHiddenPanel"/>
                <StackPanel Orientation="Horizontal" Margin="8,10,0,0">
                  <Button Name="BtnFnApply" Content="Apply profile" Style="{StaticResource AccentButton}" ToolTip="Writes only keys the in-game Video menu exposes, merged into your existing GameUserSettings.ini with a backup taken first. Engine.ini, Scalability.ini and fog/foliage cvars are never touched: Fortnite has ignored them since 2017 and FNCS rule 8.2.1 treats them as modifying the client."/>
                  <Button Name="BtnFnRestore" Content="Restore original file"/>
                  <Button Name="BtnFnLock" Content="Lock (read-only)"/>
                  <Button Name="BtnFnUnlock" Content="Unlock"/>
                  <Button Name="BtnFnShaderCache" Content="Clear shader caches"/>
                </StackPanel>
                <TextBlock Text="Launch arguments (Epic Games Launcher)" Style="{StaticResource SectionHeader}" ToolTip="Written into the Epic Games Launcher's own settings file; the launcher is closed and restarted for that. Only arguments the Unreal engine actually parses on a client are offered."/>
                <StackPanel Name="FnArgsPanel"/>
                <DockPanel Margin="8,6,8,0">
                  <TextBlock Text="extra: " VerticalAlignment="Center" Foreground="#858585"/>
                  <TextBox Name="FnArgsExtra" Text="" ToolTip="Anything else you want appended, e.g. -ResX=1920 -ResY=1080"/>
                </DockPanel>
                <TextBlock Name="FnArgsPreview" Style="{StaticResource Body}" Foreground="#DCDCAA" Text=""/>
                <StackPanel Orientation="Horizontal" Margin="8,6,0,0">
                  <Button Name="BtnFnArgsApply" Content="Write launch arguments" Style="{StaticResource AccentButton}"/>
                  <Button Name="BtnFnArgsClear" Content="Clear launch arguments"/>
                  <Button Name="BtnFnProbe" Content="Probe launcher key"/>
                  <Button Name="BtnFnProbeDone" Content="Finish probe"/>
                </StackPanel>
              </StackPanel>
            </ScrollViewer>
          </TabItem>

          <TabItem Header="NETWORK">
            <ScrollViewer VerticalScrollBarVisibility="Auto">
              <StackPanel Margin="8,4,8,16">
                <TextBlock Text="Fortnite region ping" Style="{StaticResource SectionHeader}"/>
                <StackPanel Orientation="Horizontal" Margin="8,4,0,4">
                  <Button Name="BtnPingRegions" Content="Ping regions now" Style="{StaticResource AccentButton}" ToolTip="Pings Epic's own datacenter hosts, the same ones the in-game region list measures. Pick the region with the lowest average and low jitter in Fortnite under Settings > Game > Matchmaking Region. A script cannot lower in-match ping the way ExitLag-style relays do: after your router the route is your ISP's. What does help for free is a cable instead of Wi-Fi and fixing bufferbloat on the router."/>
                  <Button Name="BtnTracert" Content="Traceroute to best region"/>
                </StackPanel>
                <TextBox Name="RegionBox" IsReadOnly="True" Height="210" Margin="8,0,8,0" Text="not measured yet" TextWrapping="NoWrap" HorizontalScrollBarVisibility="Auto" VerticalScrollBarVisibility="Auto"/>
                <TextBlock Text="DNS resolver" Style="{StaticResource SectionHeader}"/>
                <StackPanel Orientation="Horizontal" Margin="8,4,0,4">
                  <Button Name="BtnDnsBench" Content="Benchmark resolvers" ToolTip="Sends uncached queries with a real timeout to each resolver from your connection. DNS affects the launcher, login, matchmaking API and patch downloads only; it never changes in-match ping."/>
                  <Button Name="BtnDnsSet" Content="Use selected resolver" Style="{StaticResource AccentButton}"/>
                  <Button Name="BtnDnsReset" Content="Back to automatic / previous"/>
                </StackPanel>
                <Grid Margin="8,0,8,0">
                  <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="220"/><ColumnDefinition Width="*"/>
                  </Grid.ColumnDefinitions>
                  <ListBox Name="DnsList" Grid.Column="0" Height="190"/>
                  <TextBox Name="DnsBox" Grid.Column="1" IsReadOnly="True" Height="190" Margin="8,0,0,0" Text="not measured yet" TextWrapping="NoWrap" HorizontalScrollBarVisibility="Auto" VerticalScrollBarVisibility="Auto"/>
                </Grid>
                <TextBlock Text="Tools" Style="{StaticResource SectionHeader}"/>
                <StackPanel Orientation="Horizontal" Margin="8,4,0,4">
                  <Button Name="BtnLinkInfo" Content="Link info"/>
                  <Button Name="BtnFlushDns" Content="Flush DNS cache"/>
                  <Button Name="BtnNetReset" Content="Reset network stack (repair)" Style="{StaticResource DangerButton}" ToolTip="netsh winsock reset + netsh int ip reset. Fixes broken stacks; also wipes static IP/DNS and per-interface tweaks. Needs a reboot."/>
                </StackPanel>
              </StackPanel>
            </ScrollViewer>
          </TabItem>

          <TabItem Header="APPS">
            <DockPanel>
              <Border DockPanel.Dock="Top" Background="#252526" BorderBrush="#3E3E42" BorderThickness="0,0,0,1" Padding="10,8">
                <DockPanel>
                  <StackPanel DockPanel.Dock="Right" Orientation="Horizontal">
                    <Button Name="BtnInstall" Content="Install selected" Style="{StaticResource AccentButton}" Margin="0"/>
                  </StackPanel>
                  <StackPanel Orientation="Horizontal">
                    <Button Name="BtnAppsClear" Content="Clear"/>
                    <TextBlock Text="installed silently with winget" Foreground="#858585" VerticalAlignment="Center" FontSize="11"/>
                  </StackPanel>
                </DockPanel>
              </Border>
              <ScrollViewer VerticalScrollBarVisibility="Auto">
                <StackPanel Name="AppsPanel" Margin="8,4,8,16"/>
              </ScrollViewer>
            </DockPanel>
          </TabItem>


          <TabItem Header="STARTUP">
            <DockPanel>
              <Border DockPanel.Dock="Top" Background="#252526" BorderBrush="#3E3E42" BorderThickness="0,0,0,1" Padding="10,8">
                <DockPanel>
                  <StackPanel DockPanel.Dock="Right" Orientation="Horizontal">
                    <Button Name="BtnStartupDisable" Content="Disable selected" Style="{StaticResource AccentButton}" Margin="0"/>
                  </StackPanel>
                  <StackPanel Orientation="Horizontal">
                    <Button Name="BtnStartupEnable" Content="Enable selected"/>
                    <Button Name="BtnStartupRefresh" Content="Refresh"/>
                    <Button Name="BtnStartupClear" Content="Clear"/>
                  </StackPanel>
                </DockPanel>
              </Border>
              <ScrollViewer VerticalScrollBarVisibility="Auto">
                <StackPanel Margin="8,4,8,16">
                  <StackPanel Name="StartupPanel"/>
                </StackPanel>
              </ScrollViewer>
            </DockPanel>
          </TabItem>

          <TabItem Header="DEBLOAT">
            <DockPanel>
              <Border DockPanel.Dock="Top" Background="#252526" BorderBrush="#3E3E42" BorderThickness="0,0,0,1" Padding="10,8">
                <DockPanel>
                  <StackPanel DockPanel.Dock="Right" Orientation="Horizontal">
                    <Button Name="BtnDebloatRemove" Content="Remove selected" Style="{StaticResource DangerButton}" Margin="0"/>
                  </StackPanel>
                  <StackPanel Orientation="Horizontal">
                    <Button Name="BtnDebloatRecommended" Content="Select recommended"/>
                    <Button Name="BtnDebloatClear" Content="Clear"/>
                    <CheckBox Name="ChkDeprovision" Content="also for new accounts" IsChecked="True" VerticalAlignment="Center" Margin="4,0,8,0" ToolTip="Also deprovision the package so a new user account, or a Windows feature update, does not put it back."/>
                    <TextBlock Text="uninstalls apps: NOT undoable from a snapshot" Foreground="#DCDCAA" VerticalAlignment="Center" FontSize="11"/>
                  </StackPanel>
                </DockPanel>
              </Border>
              <ScrollViewer VerticalScrollBarVisibility="Auto">
                <StackPanel Margin="8,4,8,16">
                  <StackPanel Name="DebloatPanel"/>
                </StackPanel>
              </ScrollViewer>
            </DockPanel>
          </TabItem>
          <TabItem Header="INFO">
            <DockPanel>
              <Border DockPanel.Dock="Top" Background="#252526" BorderBrush="#3E3E42" BorderThickness="0,0,0,1" Padding="10,8">
                <StackPanel Orientation="Horizontal">
                  <Button Name="BtnOpenLogs" Content="Open log folder"/>
                  <Button Name="BtnOpenBackups" Content="Open backup folder"/>
                  <Button Name="BtnRefreshInfo" Content="Refresh"/>
                </StackPanel>
              </Border>
              <TextBox Name="InfoBox" IsReadOnly="True" Margin="8" TextWrapping="NoWrap" HorizontalScrollBarVisibility="Auto" VerticalScrollBarVisibility="Auto" BorderThickness="0" Text="collecting..."/>
            </DockPanel>
          </TabItem>
        </TabControl>
      </Grid>

      <GridSplitter Grid.Row="1" HorizontalAlignment="Stretch" VerticalAlignment="Stretch"/>
      <DockPanel Grid.Row="2" Background="#1E1E1E">
        <Border DockPanel.Dock="Top" Background="#252526" BorderBrush="#3E3E42" BorderThickness="0,0,0,1" Padding="10,3">
          <DockPanel>
            <Button Name="BtnClearLog" Content="clear" DockPanel.Dock="Right" Padding="8,1" FontSize="11" Margin="0"/>
            <TextBlock Text="OUTPUT" Foreground="#858585" FontSize="11" VerticalAlignment="Center"/>
          </DockPanel>
        </Border>
        <TextBox Name="ConsoleBox" IsReadOnly="True" IsReadOnlyCaretVisible="False" AcceptsReturn="True" TextWrapping="NoWrap"
                 VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Auto" BorderThickness="0" FontSize="12"/>
      </DockPanel>
    </Grid>
  </DockPanel>
</Window>
'@

# ---------------------------------------------------------------------------------------------
# unknowntweaks entry point. Everything above this block (functions, configs, XAML) is compiled in.
# Runs on Windows PowerShell 5.1 as administrator, single-threaded apartment, FullLanguage mode.
# ---------------------------------------------------------------------------------------------

if ($ExecutionContext.SessionState.LanguageMode -ne 'FullLanguage') {
    Write-Host 'unknowntweaks cannot run here: PowerShell is in a restricted language mode (AppLocker / WDAC).' -ForegroundColor Red
    return
}

$UTPowerShell51 = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
$UTFromFile = -not [string]::IsNullOrEmpty($PSCommandPath)
if ($UTFromFile) {
    $UTRelaunchCommand = "& '" + ($PSCommandPath -replace "'", "''") + "'"
} elseif ($sync.url -match 'YOUR-ANON-ACCOUNT') {
    # This build was never given a real download URL. Re-downloading from a placeholder address and
    # running the result as administrator is exactly how a supply-chain attack would work, so don't.
    Write-Host 'This build of unknowntweaks was compiled without a real download URL, so it cannot relaunch itself.' -ForegroundColor Red
    Write-Host 'Either run it from an elevated Windows PowerShell window, or rebuild it with: .\Compile.ps1 -Owner <your-github-account>' -ForegroundColor Yellow
    return
} else {
    $UTRelaunchCommand = "[Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor 3072; irm '" + $sync.url + "' | iex"
}
$UTEncoded = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($UTRelaunchCommand))

$UTIsAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
$UTIsDesktop51 = ($PSVersionTable.PSEdition -eq 'Desktop' -and $PSVersionTable.PSVersion.Major -eq 5)
$UTIsSta = ([System.Threading.Thread]::CurrentThread.GetApartmentState() -eq 'STA')

if (-not $UTIsAdmin -or -not $UTIsDesktop51 -or -not $UTIsSta) {
    if (-not $UTIsAdmin) { Write-Host 'unknowntweaks needs administrator rights. Asking for elevation...' -ForegroundColor Yellow }
    elseif (-not $UTIsDesktop51) { Write-Host 'Relaunching in Windows PowerShell 5.1 (needed for the interface and restore points)...' -ForegroundColor Yellow }
    else { Write-Host 'Relaunching in a single-threaded apartment (needed for the interface)...' -ForegroundColor Yellow }
    try {
        $UTArgs = @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-STA', '-EncodedCommand', $UTEncoded)
        if ($UTIsAdmin) { Start-Process -FilePath $UTPowerShell51 -ArgumentList $UTArgs -ErrorAction Stop }
        else { Start-Process -FilePath $UTPowerShell51 -ArgumentList $UTArgs -Verb RunAs -ErrorAction Stop }
    } catch {
        Write-Host ('Could not relaunch: ' + $_.Exception.Message) -ForegroundColor Red
    }
    return
}

[Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
$ErrorActionPreference = 'Continue'

# ---- private beta gate ---------------------------------------------------------------------
# A beta build asks the gate once, here, in the final elevated process, and stops if the key was
# revoked or the beta was closed. Public builds carry no status URL and skip this entirely.
if ($sync.statusUrl) {
    $UTGate = Test-UTBetaGate -StatusUrl $sync.statusUrl -Version $sync.version
    if (-not $UTGate.Ok) {
        Write-Host ('This private beta build is not active ({0}). Ask in the Discord for a current one-liner.' -f $UTGate.Reason) -ForegroundColor Red
        Start-Sleep -Seconds 8
        return
    }
}

# ---- shared state --------------------------------------------------------------------------
$sync.dir       = Join-Path $env:ProgramData 'unknowntweaks'
$sync.backupDir = Join-Path $sync.dir 'backup'
$sync.logDir    = Join-Path $env:LOCALAPPDATA 'unknowntweaks\logs'
foreach ($d in @($sync.dir, $sync.backupDir, $sync.logDir)) { if (-not (Test-Path -LiteralPath $d)) { New-Item -ItemType Directory -Path $d -Force | Out-Null } }
$sync.logPath   = Join-Path $sync.logDir ('unknowntweaks_{0:yyyy-MM-dd_HH-mm-ss}.log' -f (Get-Date))
$sync.log       = New-Object 'System.Collections.Concurrent.ConcurrentQueue[string]'
$sync.jobDone   = New-Object 'System.Collections.Concurrent.ConcurrentQueue[string]'
$sync.jobs      = New-Object System.Collections.ArrayList
$sync.metrics   = [hashtable]::Synchronized(@{ Snapshot = $null })
$sync.busy      = $false
$sync.closing   = $false
$sync.needReboot = $false
$sync.status    = 'ready'
$sync.graphs    = @{}
$sync.tweakBoxes = @{}
$sync.appBoxes  = @{}
$sync.startupBoxes = @{}
$sync.debloatBoxes = @{}
$sync.fnHiddenBoxes = @{}
$sync.fnArgBoxes = @{}
$sync.fnArgExcludes = @{}
$sync.fnArgOrder = @()
$sync.lastTick  = 0
$sync.consoleLines = 0
$sync.tweakStates = @{}
$sync.regions   = $null
$sync.bestRegion = 'not measured yet'
$sync.dnsResults = $null
$sync.form      = $null

Write-UTLog ('unknowntweaks {0} starting (PowerShell {1}, {2})' -f $sync.version, $PSVersionTable.PSVersion, $(if ($UTFromFile) { 'from file' } else { 'from the one-liner' }))
Write-UTLog ('log file: ' + $sync.logPath)

# ---- native helpers, DPI, WPF ---------------------------------------------------------------
$UTNative = Initialize-UTNative
# powershell.exe already declares DPI awareness in its manifest, so this normally returns
# E_ACCESSDENIED and is a no-op; ask only for what WPF on .NET Framework can honour anyway.
if ($UTNative) { try { [void][UT.NativeV1.Dwm]::SetProcessDpiAwareness(1) } catch { } }
Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase

# The boot screen covers the seconds it takes to collect system info and build the window. It is
# cosmetic only: if it cannot be shown, $UTSplash is $null and everything below runs the same.
$UTSplash = Show-UTSplash -Beta:([bool]$sync.beta)

Write-UTLog 'collecting system information...'
$sync.sysinfo = Get-UTSystemInfo

# ---- window ---------------------------------------------------------------------------------
[xml]$UTXaml = $inputXML
$UTReader = New-Object System.Xml.XmlNodeReader $UTXaml
try {
    $sync.form = [Windows.Markup.XamlReader]::Load($UTReader)
} catch {
    $ex = $_.Exception
    while ($ex.InnerException) { $ex = $ex.InnerException }
    Write-Host ('The interface could not be built: ' + $ex.Message) -ForegroundColor Red
    Close-UTSplash -Window $UTSplash -MinimumMs 0
    return
}
# $sync is case-insensitive and already holds shared state, so a control named e.g. "status" would
# silently overwrite it. Fail loudly instead of corrupting state at runtime.
$UTXaml.SelectNodes('//*[@Name]') | ForEach-Object {
    $n = $_.Name
    if ($sync.ContainsKey($n)) { throw "The XAML element Name='$n' collides with an internal state key; rename it." }
    $sync[$n] = $sync.form.FindName($n)
}

if ($UTNative) {
    $sync.form.Add_SourceInitialized({
        try {
            $hwnd = (New-Object System.Windows.Interop.WindowInteropHelper -ArgumentList $this).Handle
            $on = 1
            if ([UT.NativeV1.Dwm]::DwmSetWindowAttribute($hwnd, 20, [ref]$on, 4) -ne 0) { [void][UT.NativeV1.Dwm]::DwmSetWindowAttribute($hwnd, 19, [ref]$on, 4) }
            if ([Environment]::OSVersion.Version.Build -ge 22000) {
                # COLORREF is 0x00BBGGRR, so the bytes are the reverse of an HTML colour.
                $cap = 0x001E1E1E   # #1E1E1E is neutral grey, identical either way
                [void][UT.NativeV1.Dwm]::DwmSetWindowAttribute($hwnd, 35, [ref]$cap, 4)
                $bdr = 0x00423E3E   # #3E3E42
                [void][UT.NativeV1.Dwm]::DwmSetWindowAttribute($hwnd, 34, [ref]$bdr, 4)
            }
        } catch { }
    })
}

Initialize-UTUI
Start-UTMonitor
Start-UTUITimer

$sync.form.Add_Loaded({
    try {
        foreach ($g in $sync.graphs.Values) { Update-UTGraph -Graph $g }
        Write-UTLog ('ready. {0} | {1} | {2} GB RAM | {3}' -f $sync.sysinfo.CPU, $sync.sysinfo.GPU, $sync.sysinfo.RamGB, $sync.sysinfo.OSName) -Level Ok
        Write-UTLog 'Everything applied here is recorded first and can be undone from the same list. No warranty: hover a tweak before ticking it.' -Level Warn
        # -Background: this runs unasked at startup, so it must not grey out every button for 15 seconds.
        [void](Start-UTUIJob -Kind 'regions' -Background -Script 'Start-Sleep -Milliseconds 1500; Measure-UTRegionPing | Out-Null')
    } catch { Write-UTLog ('startup: ' + $_.Exception.Message) -Level Error }
})
$sync.form.Add_Closing({
    param($closingSender, $closingArgs)
    try {
        if ($sync.busy) {
            $r = [System.Windows.MessageBox]::Show('A task is still running. Close anyway?', 'unknowntweaks', [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Question)
            if ($r -ne [System.Windows.MessageBoxResult]::Yes) { $closingArgs.Cancel = $true; return }
        }
        $sync.closing = $true
        if ($sync.timer) { $sync.timer.Stop() }
    } catch { }
})

Close-UTSplash -Window $UTSplash
[void]$sync.form.ShowDialog()

# ---- shutdown -------------------------------------------------------------------------------
$sync.closing = $true
try { if ($sync.timer) { $sync.timer.Stop() } } catch { }
Stop-UTMonitor
Stop-UTJobs
Write-UTLog 'closed'

